//! The hash database: Vonksdesu/petrascyll's ZZZ-Mod-Fixer character data,
//! flattened from 100 per-character Python modules into one JSON asset.
//!
//! The asset is generated by `assets/zzz-mod-fixer/generate_database.py`, which
//! is the only thing allowed to write it - see `assets/zzz-mod-fixer/NOTICE.md`
//! for provenance and licensing. Command names and argument names are kept
//! verbatim; the engine matches on them, and anything it does not implement is
//! reported instead of being dropped.

use std::collections::HashMap;
use std::sync::LazyLock;

use serde::Deserialize;

/// Bundled database. ~2.3 MiB of JSON, compiled into the binary so fixing works
/// offline - the reason this feature exists at all.
const ASSET: &str = include_str!("../../assets/zzz-mod-fixer/database.json");

/// Commands that rewrite `.buf` files. v1 reports them and never runs them.
pub const BUFFER_COMMANDS: [&str; 3] = [
    "update_buffer_blend_indices",
    "zzz_12_shrink_texcoord_color",
    "zzz_13_remap_texcoord",
];

#[derive(Debug, Deserialize)]
pub struct SourceInfo {
    pub repo: String,
    #[serde(rename = "ref")]
    pub git_ref: String,
    #[serde(rename = "refDate")]
    pub ref_date: String,
    #[serde(rename = "gameVersion")]
    pub game_version: String,
    pub license: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DatabaseFile {
    pub source: SourceInfo,
    pub characters: u32,
    pub hash_count: u32,
    pub hash_commands: HashMap<String, Entry>,
}

/// One hash's fix, as written upstream.
#[derive(Debug, Clone, Deserialize)]
pub struct Entry {
    /// Character module the entry came from (later modules win on collisions,
    /// exactly like upstream's `dict.update`).
    pub character: String,
    /// Human label; upstream's first `log` line for the hash.
    pub label: String,
    pub commands: Vec<RawCommand>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct RawCommand {
    pub cmd: String,
    #[serde(default)]
    pub args: serde_json::Value,
}

impl RawCommand {
    pub fn str_arg(&self, name: &str) -> Option<&str> {
        self.args.get(name).and_then(|value| value.as_str())
    }

    /// `equiv_hashes` is a single hash or a list of them upstream.
    pub fn hashes_arg(&self, name: &str) -> Vec<String> {
        match self.args.get(name) {
            Some(serde_json::Value::String(single)) => vec![single.clone()],
            Some(serde_json::Value::Array(items)) => items
                .iter()
                .filter_map(|item| item.as_str().map(str::to_string))
                .collect(),
            _ => Vec::new(),
        }
    }
}

#[derive(Debug)]
pub struct Database {
    file: DatabaseFile,
}

impl Database {
    /// Parse a database asset. Exposed so tests can run the engine against
    /// synthetic data (including commands the real asset never contains).
    pub fn from_json(text: &str) -> Result<Database, serde_json::Error> {
        Ok(Database {
            file: serde_json::from_str(text)?,
        })
    }

    /// The bundled database, parsed once on first use.
    pub fn bundled() -> &'static Database {
        static BUNDLED: LazyLock<Database> = LazyLock::new(|| {
            let database = Database::from_json(ASSET).unwrap_or_else(|error| {
                // A malformed bundled asset is a build-time mistake; the test
                // suite catches it before it can ship.
                panic!("bundled hash database is not valid JSON: {error}")
            });

            let source = database.source();
            log::info!(
                "Fixer hash database: {} hashes, {} characters, {}@{} ({}), game {}, {}",
                database.hash_count(),
                database.character_count(),
                source.repo,
                &source.git_ref[..8.min(source.git_ref.len())],
                source.ref_date,
                source.game_version,
                source.license
            );

            database
        });

        &BUNDLED
    }

    pub fn get(&self, hash: &str) -> Option<&Entry> {
        self.file.hash_commands.get(&hash.to_ascii_lowercase())
    }

    pub fn source(&self) -> &SourceInfo {
        &self.file.source
    }

    pub fn hash_count(&self) -> u32 {
        self.file.hash_count
    }

    pub fn character_count(&self) -> u32 {
        self.file.characters
    }
}

/// True for the buffer-level commands v1 detects but never executes.
pub fn is_buffer_command(command: &str) -> bool {
    BUFFER_COMMANDS.contains(&command)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fixer::engine;

    #[test]
    fn bundled_database_parses_and_matches_its_own_metadata() {
        let database = Database::bundled();

        assert_eq!(database.hash_count() as usize, {
            let file: DatabaseFile = serde_json::from_str(ASSET).expect("asset");
            file.hash_commands.len()
        });
        assert!(database.character_count() >= 85, "every character module ships");
        assert!(database.get("3c8697e8").is_some());
        assert!(database.get("zzz").is_none(), "unknown hashes are absent");
        assert!(database.source().license.contains("MIT"));
    }

    #[test]
    fn every_declared_command_is_known() {
        // Read the shipped asset's own manifests, not the parsed structs: this
        // is a check on the data a regeneration would produce.
        let asset: serde_json::Value = serde_json::from_str(ASSET).expect("asset");
        let declared = asset["commands"]["used"]
            .as_array()
            .expect("commands.used")
            .iter()
            .chain(asset["commands"]["bufferPass"].as_array().expect("bufferPass"))
            .filter_map(serde_json::Value::as_str);

        let unportable: Vec<&str> = declared
            .filter(|command| !engine::knows(command))
            .collect();

        assert!(
            unportable.is_empty(),
            "the asset declares commands the engine neither implements nor reports: {unportable:?}"
        );
    }

    #[test]
    fn a_malformed_asset_is_rejected() {
        assert!(Database::from_json("{ not json").is_err());
    }
}
